const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([100.141422, 20.248364]);
  const buffer = point.buffer(500); // 500m buffer around the point

  const date2015 = '2015-01-27';
  const date2020 = '2020-01-25';

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  const getL8Collection = function(startDate, endDate) {
    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(point)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
  };

  const col2015 = getL8Collection(date2015, ee.Date(date2015).advance(1, 'day'));
  const col2020 = getL8Collection(date2020, ee.Date(date2020).advance(1, 'day'));

  const size2015 = col2015.size().getInfo();
  const size2020 = col2020.size().getInfo();

  console.log(`2015 Images: ${size2015}, 2020 Images: ${size2020}`);

  if (size2015 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the best image (least cloud cover) for each date
  const img2015 = col2015.sort('CLOUD_COVER').first();
  const img2020 = col2020.sort('CLOUD_COVER').first();

  // 3. Processing - Cloud masking and sediment analysis
  // Use SWIR1 band (band 6) as proxy for sediment (higher reflectance = more sediment)
  // Also calculate NDWI to identify water pixels

  const addNDWI = function(image) {
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI'); // Green - NIR
    return image.addBands(ndwi);
  };

  const img2015_processed = addNDWI(img2015);
  const img2020_processed = addNDWI(img2020);

  // Mask to water pixels (NDWI > 0) and get SWIR1 reflectance
  const getSedimentValue = function(image) {
    const waterMask = image.select('NDWI').gt(0.1); // Water pixels
    const sedimentBand = image.select('SR_B6').updateMask(waterMask); // SWIR1 band

    const stats = sedimentBand.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: buffer,
      scale: 30,
      maxPixels: 1e9
    });

    return stats;
  };

  const stats2015 = getSedimentValue(img2015_processed).getInfo();
  const stats2020 = getSedimentValue(img2020_processed).getInfo();

  console.log(`2015 SWIR1: ${stats2015?.mean?.toFixed(4)} (px: ${stats2015?.count})`);
  console.log(`2020 SWIR1: ${stats2020?.mean?.toFixed(4)} (px: ${stats2020?.count})`);

  // 4. Validation & Final Answer
  if (!stats2015 || !stats2020 || stats2015.count === 0 || stats2020.count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (stats2015.mean === null || stats2020.mean === null || 
      isNaN(stats2015.mean) || isNaN(stats2020.mean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare sediment levels (higher SWIR1 reflectance = more sediment)
  const sediment2015 = stats2015.mean;
  const sediment2020 = stats2020.mean;

  console.log(`Sediment 2015: ${sediment2015.toFixed(4)}, 2020: ${sediment2020.toFixed(4)}`);

  if (sediment2015 > sediment2020) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
